export const API_KEY_EXPIRY_OPTIONS = ["30", "90", "365", "never"] as const;

export type ApiKeyExpiryOption = (typeof API_KEY_EXPIRY_OPTIONS)[number];

export const API_KEY_EXPIRY_LABELS: Record<ApiKeyExpiryOption, string> = {
  "30": "30 days",
