/**
 * The one error shape of the public API:
 * `{ error: { code, message, details?, requestId } }`.
 *
 * Throw `ApiError` from a v1 handler (or anything it calls) to answer with a
 * specific status; any other throw becomes a generic 500 whose message never
 * includes the original error.
 */

export const API_ERROR_CODES = [
  "invalid_request",
  "unauthorized",
  "plan_required",
  "forbidden",
  "not_found",
  "method_not_allowed",
  "conflict",
  "idempotency_key_reused",
  "payload_too_large",
  "unsupported_media_type",
  "limit_reached",
  "rate_limited",
  "quota_exceeded",
  "internal_error",
] as const;

export type ApiErrorCode = (typeof API_ERROR_CODES)[number];

export const API_ERROR_STATUS: Record<ApiErrorCode, number> = {
  invalid_request: 400,
  unauthorized: 401,
  plan_required: 403,
  forbidden: 403,
  not_found: 404,
  method_not_allowed: 405,
  conflict: 409,
  idempotency_key_reused: 422,
  payload_too_large: 413,
  unsupported_media_type: 415,
  limit_reached: 409,
  rate_limited: 429,
  quota_exceeded: 429,
  internal_error: 500,
};

export class ApiError extends Error {
  readonly code: ApiErrorCode;
  readonly status: number;
  readonly details?: unknown;
  readonly headers?: Record<string, string>;

  constructor(
    code: ApiErrorCode,
    message: string,
    options: { details?: unknown; headers?: Record<string, string> } = {},
  ) {
    super(message);
    this.name = "ApiError";
    this.code = code;
    this.status = API_ERROR_STATUS[code];
    this.details = options.details;
    this.headers = options.headers;
  }
}

export type ApiErrorBody = {
  error: {
    code: ApiErrorCode;
    message: string;
    details?: unknown;
    requestId: string;
  };
};

export function apiErrorBody(error: ApiError, requestId: string): ApiErrorBody {
  return {
    error: {
      code: error.code,
      message: error.message,
      ...(error.details !== undefined ? { details: error.details } : {}),
      requestId,
    },
  };
}

export const INTERNAL_ERROR_MESSAGE =
  "Something went wrong on our side. Retry later and quote the requestId if it keeps happening.";

export function notFound(what: string): ApiError {
  return new ApiError("not_found", `${what} not found.`);
}

/**
 * Per-key request rate limiting for the public API.
 *
 * Sliding-window counter: one counter per key per fixed minute, and the
 * request rate is estimated as `previous * (1 - elapsed/window) + current`.
 * That smooths the burst a fixed window allows at the boundary without
 * storing one row per request. Rejected requests are not counted.
 *
 * `RateLimiter` is the seam for moving to Upstash/Redis later: the handler
 * only depends on the interface.
 */

import { prisma } from "@/db";

export const RATE_LIMIT_WINDOW_MS = 60_000;

export type RateLimitResult = {
  allowed: boolean;
  limit: number;
  remaining: number;
  /** End of the current fixed window (X-RateLimit-Reset). */
  resetAt: Date;
  /** Seconds until a request would be allowed again (0 when allowed). */
  retryAfterSeconds: number;
};

export interface RateLimiter {
  consume(bucket: string, limit: number, now?: Date): Promise<RateLimitResult>;
}

function windowStartOf(now: Date, windowMs: number): Date {
  return new Date(Math.floor(now.getTime() / windowMs) * windowMs);
}

/**
 * Pure decision for one request. `current` already includes this request.
 * Exported for tests and for alternative stores.
 */
export function slidingWindowDecision(input: {
  previous: number;
  current: number;
  limit: number;
  now: Date;
  windowMs?: number;
}): RateLimitResult {
  const windowMs = input.windowMs ?? RATE_LIMIT_WINDOW_MS;
  const windowStart = windowStartOf(input.now, windowMs);
  const elapsed = input.now.getTime() - windowStart.getTime();
  const previousWeight = 1 - elapsed / windowMs;
  const estimate = input.previous * previousWeight + input.current;
  const resetAt = new Date(windowStart.getTime() + windowMs);

  if (estimate <= input.limit) {
    return {
      allowed: true,
      limit: input.limit,
      remaining: Math.max(0, Math.floor(input.limit - estimate)),
      resetAt,
      retryAfterSeconds: 0,
    };
  }

  // Without this request the window holds `current - 1`. Find the first
  // moment `previous * (1 - t/window) + current <= limit`.
  let waitMs: number;
  if (input.current > input.limit || input.previous === 0) {
    waitMs = resetAt.getTime() - input.now.getTime();
  } else {
    const needed = windowMs * (1 - (input.limit - input.current) / input.previous);
    waitMs = Math.max(0, needed - elapsed);
  }

  return {
    allowed: false,
    limit: input.limit,
    remaining: 0,
    resetAt,
    retryAfterSeconds: Math.max(1, Math.ceil(waitMs / 1000)),
  };
}

export class PostgresRateLimiter implements RateLimiter {
  constructor(private readonly windowMs = RATE_LIMIT_WINDOW_MS) {}

  async consume(bucket: string, limit: number, now = new Date()): Promise<RateLimitResult> {
    const windowStart = windowStartOf(now, this.windowMs);
    const previousStart = new Date(windowStart.getTime() - this.windowMs);

    // Count first (atomic upsert), then undo if over the limit, so concurrent
    // requests can never all slip in on the same read.
    const [row] = await prisma.$queryRaw<{ current: number; previous: number }[]>`
      WITH bumped AS (
        INSERT INTO api_rate_limit_windows (bucket, window_start, count)
        VALUES (${bucket}, ${windowStart}, 1)
        ON CONFLICT (bucket, window_start)
        DO UPDATE SET count = api_rate_limit_windows.count + 1
        RETURNING count
      )
      SELECT
        (SELECT count FROM bumped)::int AS current,
        COALESCE((
          SELECT count FROM api_rate_limit_windows
          WHERE bucket = ${bucket} AND window_start = ${previousStart}
        ), 0)::int AS previous
    `;

    const decision = slidingWindowDecision({
      previous: row?.previous ?? 0,
      current: row?.current ?? 1,
      limit,
      now,
      windowMs: this.windowMs,
    });

    if (!decision.allowed) {
      await prisma.$executeRaw`
        UPDATE api_rate_limit_windows SET count = count - 1
        WHERE bucket = ${bucket} AND window_start = ${windowStart} AND count > 0
      `;
    }
    return decision;
  }
}

/** In-process limiter with the same math; for tests and local scripts. */
export class MemoryRateLimiter implements RateLimiter {
  private readonly counts = new Map<string, number>();

  constructor(private readonly windowMs = RATE_LIMIT_WINDOW_MS) {}

  async consume(bucket: string, limit: number, now = new Date()): Promise<RateLimitResult> {
    const windowStart = windowStartOf(now, this.windowMs).getTime();
    const currentKey = `${bucket}|${windowStart}`;
    const previousKey = `${bucket}|${windowStart - this.windowMs}`;
    const current = (this.counts.get(currentKey) ?? 0) + 1;
    const decision = slidingWindowDecision({
      previous: this.counts.get(previousKey) ?? 0,
      current,
      limit,
      now,
      windowMs: this.windowMs,
    });
    if (decision.allowed) {
      this.counts.set(currentKey, current);
    }
    return decision;
  }
}

/** Daily cleanup: windows older than `olderThan` are never read again. */
export async function deleteOldRateLimitWindows(olderThan: Date): Promise<number> {
  const result = await prisma.apiRateLimitWindow.deleteMany({
    where: { windowStart: { lt: olderThan } },
  });
  return result.count;
}

/**
 * `Idempotency-Key` support for pipeline POSTs. A key is remembered for 24h per
 * user: the same key + same request replays the stored response, the same key
 * with a different request is rejected, and a key whose first request is
 * still running answers 409. 5xx responses are not stored, so they can be
 * retried with the same key.
 */

import { createHash } from "node:crypto";
import { Prisma } from "@/db/generated/client";
import { prisma } from "@/db";

export const IDEMPOTENCY_TTL_MS = 24 * 60 * 60 * 1000;
export const IDEMPOTENCY_KEY_PATTERN = /^[\x21-\x7e]{1,255}$/;

export type IdempotencyScope = {
  userId: string;
  key: string;
  method: string;
  path: string;
  requestHash: string;
};

export type IdempotencyBegin =
  | { kind: "new" }
  | { kind: "replay"; status: number; body: unknown }
  | { kind: "in_progress" }
  | { kind: "mismatch" };

export interface IdempotencyStore {
  begin(scope: IdempotencyScope, now?: Date): Promise<IdempotencyBegin>;
  complete(userId: string, key: string, status: number, body: unknown): Promise<void>;
  release(userId: string, key: string): Promise<void>;
}

/** Key order never changes the hash. */
export function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map(canonicalJson).join(",")}]`;
  }
  if (value && typeof value === "object") {
    const entries = Object.entries(value as Record<string, unknown>)
      .filter(([, v]) => v !== undefined)
      .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return `{${entries.map(([k, v]) => `${JSON.stringify(k)}:${canonicalJson(v)}`).join(",")}}`;
  }
  return JSON.stringify(value ?? null);
}

export function hashRequest(method: string, path: string, body: unknown): string {
  return createHash("sha256")
    .update(`${method.toUpperCase()} ${path}\n${canonicalJson(body)}`)
    .digest("hex");
}

function matches(row: { method: string; path: string; requestHash: string }, scope: IdempotencyScope) {
  return (
    row.method === scope.method &&
    row.path === scope.path &&
    row.requestHash === scope.requestHash
  );
}

export class PostgresIdempotencyStore implements IdempotencyStore {
  async begin(scope: IdempotencyScope, now = new Date()): Promise<IdempotencyBegin> {
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        await prisma.apiIdempotencyKey.create({
          data: {
            userId: scope.userId,
            key: scope.key,
            method: scope.method,
            path: scope.path,
            requestHash: scope.requestHash,
          },
        });
        return { kind: "new" };
      } catch (error) {
        if (
          !(error instanceof Prisma.PrismaClientKnownRequestError) ||
          error.code !== "P2002"
        ) {
          throw error;
        }
      }

      const existing = await prisma.apiIdempotencyKey.findUnique({
        where: { userId_key: { userId: scope.userId, key: scope.key } },
      });
      if (!existing) {
        continue;
      }
      if (existing.createdAt.getTime() <= now.getTime() - IDEMPOTENCY_TTL_MS) {
        // Expired: forget it and try to claim the key again.
        await prisma.apiIdempotencyKey.deleteMany({
          where: { id: existing.id, createdAt: existing.createdAt },
        });
        continue;
      }
      if (!matches(existing, scope)) {
        return { kind: "mismatch" };
      }
      if (existing.responseStatus == null) {
        return { kind: "in_progress" };
      }
      return {
        kind: "replay",
        status: existing.responseStatus,
        body: existing.responseBody,
      };
    }
    return { kind: "in_progress" };
  }

  async complete(userId: string, key: string, status: number, body: unknown) {
    await prisma.apiIdempotencyKey.updateMany({
      where: { userId, key },
      data: {
        responseStatus: status,
        responseBody: (body ?? null) as Prisma.InputJsonValue,
      },
    });
  }

  async release(userId: string, key: string) {
    await prisma.apiIdempotencyKey.deleteMany({
      where: { userId, key, responseStatus: null },
    });
  }
}

/** In-process store with the same rules; for tests. */
export class MemoryIdempotencyStore implements IdempotencyStore {
  readonly rows = new Map<
    string,
    IdempotencyScope & { createdAt: Date; status: number | null; body: unknown }
  >();

  async begin(scope: IdempotencyScope, now = new Date()): Promise<IdempotencyBegin> {
    const id = `${scope.userId}|${scope.key}`;
    const existing = this.rows.get(id);
    if (!existing || existing.createdAt.getTime() <= now.getTime() - IDEMPOTENCY_TTL_MS) {
      this.rows.set(id, { ...scope, createdAt: now, status: null, body: null });
      return { kind: "new" };
    }
    if (!matches(existing, scope)) return { kind: "mismatch" };
    if (existing.status == null) return { kind: "in_progress" };
    return { kind: "replay", status: existing.status, body: existing.body };
  }

  async complete(userId: string, key: string, status: number, body: unknown) {
    const row = this.rows.get(`${userId}|${key}`);
    if (row) {
      row.status = status;
      row.body = structuredClone(body);
    }
  }

  async release(userId: string, key: string) {
    const id = `${userId}|${key}`;
    if (this.rows.get(id)?.status == null) this.rows.delete(id);
  }
}

export async function deleteExpiredIdempotencyKeys(now = new Date()): Promise<number> {
  const result = await prisma.apiIdempotencyKey.deleteMany({
    where: { createdAt: { lt: new Date(now.getTime() - IDEMPOTENCY_TTL_MS) } },
  });
  return result.count;
}

/**
 * Opaque keyset cursors. Clients pass `nextCursor` back verbatim; the content
 * (sort key + id of the last row) is an implementation detail and may change.
 */

import { z } from "zod";
import { ApiError } from "@/lib/api/v1/errors";

const cursorSchema = z.object({
  /** Sort timestamp of the last row (ISO), or null for rows without one. */
  t: z.iso.datetime().nullable(),
  /** Id of the last row (tie-breaker). */
  id: z.string().min(1).max(64),
});

export type Cursor = z.infer<typeof cursorSchema>;

export function encodeCursor(cursor: { t: Date | null; id: string }): string {
  const payload: Cursor = { t: cursor.t?.toISOString() ?? null, id: cursor.id };
  return Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
}

export function decodeCursor(raw: string | undefined): { t: Date | null; id: string } | null {
  if (raw === undefined) {
    return null;
  }
  try {
    const parsed = cursorSchema.parse(
      JSON.parse(Buffer.from(raw, "base64url").toString("utf8")),
    );
    return { t: parsed.t ? new Date(parsed.t) : null, id: parsed.id };
  } catch {
    throw new ApiError("invalid_request", "cursor is not valid. Pass nextCursor back unchanged.", {
      details: { fieldErrors: { cursor: ["Invalid cursor"] } },
    });
  }
}

/**
 * Page from `limit + 1` rows ordered by (sortKey desc, id desc): the extra row
 * only tells whether another page exists.
 */
export function pageFromRows<T extends { id: string }>(
  rows: T[],
  limit: number,
  sortKey: (row: T) => Date | null,
): { items: T[]; nextCursor: string | null } {
  const items = rows.slice(0, limit);
  const last = items[items.length - 1];
  const nextCursor =
    rows.length > limit && last ? encodeCursor({ t: sortKey(last), id: last.id }) : null;
  return { items, nextCursor };
}

/**
 * Prisma `where` for "after this cursor" on (field desc nulls last, id desc).
 */
export function afterCursorWhere(field: string, cursor: { t: Date | null; id: string } | null) {
  if (!cursor) {
    return {};
  }
  if (cursor.t === null) {
    return { [field]: null, id: { lt: cursor.id } };
  }
  return {
    OR: [
      { [field]: { lt: cursor.t } },
      { [field]: cursor.t, id: { lt: cursor.id } },
      { [field]: null },
    ],
  };
}

