  unauthorized: "Missing, malformed, unknown, revoked or expired key.",
  plan_required: "The key's account is not on an active Pro plan. Keys work again as soon as Pro is renewed.",
  forbidden: "The key lacks the scope the endpoint needs (`details.requiredScope`).",
  not_found: "No such resource, or it isn't yours. Malformed ids also answer 404.",
  method_not_allowed: "The path exists but not with this HTTP method.",
  conflict:
    "The request clashes with existing state: a briefing with different parameters (`details.existingBriefingId`), or an Idempotency-Key whose first request is still running.",
  idempotency_key_reused: "The Idempotency-Key was already used with a different request body or path.",
  payload_too_large: "Request body over 64 KB.",
  unsupported_media_type: "Bodies must be JSON with `Content-Type: application/json`.",
  limit_reached: "An account limit was reached (e.g. the maximum number of newsletters).",
  rate_limited: "Too many requests for this key in the last minute. Wait `Retry-After` seconds.",
  quota_exceeded: "Daily pipeline quota used up. It resets at 00:00 UTC (`Retry-After`, `details.resetsAt`).",
  internal_error: "Unexpected server error. Retry with backoff; quote the `requestId` if it persists.",
};

function scopesTable(): string {
  return [
    "| Scope | Grants |",
    "| --- | --- |",
    ...API_SCOPES.map((scope) => `| \`${scope}\` | ${API_SCOPE_DESCRIPTIONS[scope]} |`),
  ].join("\n");
}

function errorsTable(): string {
  return [
    "| HTTP | `code` | Meaning |",
    "| --- | --- | --- |",
    ...API_ERROR_CODES.map(
      (code) => `| ${API_ERROR_STATUS[code]} | \`${code}\` | ${ERROR_DESCRIPTIONS[code]} |`,
    ),
  ].join("\n");
}

function changelog(): string {
  return API_CHANGELOG.map(
    (entry) => `**${entry.version}** — ${entry.date}\n\n${entry.notes.map((n) => `- ${n}`).join("\n")}`,
  ).join("\n\n");
}

export function apiDocsMarkdown(input: { baseUrl: string; limits: ApiPlanLimits }): string {
  const api = `${input.baseUrl}/api/v1`;
  const { limits } = input;
  return `
The Dainik Samachar API gives your code the same briefings, research reports, instrument search and newsletters as the app. JSON over HTTPS, one version (\`/api/v1\`), keys per account.

> **Requires Pro.** Every endpoint needs an API key from an account on an active Pro plan. Create keys under **Settings → Developers**. If the plan lapses, keys answer \`403 plan_required\` until Pro is renewed; they are not deleted.

## Quickstart

1. Upgrade to Pro and create a key on the Developers page. Copy it — it is shown once.
2. Call \`GET /me\` to check the key, its scopes and your quota.
3. Start a briefing, then poll its job (or pass a \`webhookUrl\`).

**curl**

\`\`\`bash
export DS_API_KEY="ds_live_..."

curl ${api}/me -H "Authorization: Bearer $DS_API_KEY"

curl -X POST ${api}/news/briefings \\
  -H "Authorization: Bearer $DS_API_KEY" \\
  -H "Content-Type: application/json" \\
  -H "Idempotency-Key: $(uuidgen)" \\
  -d '{"scope":"world","storyCount":5,"categories":["markets"]}'
# → 202 { "id": "<job id>", "status": "pending", ... }

curl ${api}/jobs/<job id> -H "Authorization: Bearer $DS_API_KEY"
\`\`\`

**JavaScript (Node 18+)**

\`\`\`js
const API = "${api}";
const headers = {
  Authorization: \`Bearer \${process.env.DS_API_KEY}\`,
  "Content-Type": "application/json",
};

const res = await fetch(\`\${API}/news/briefings\`, {
  method: "POST",
  headers: { ...headers, "Idempotency-Key": crypto.randomUUID() },
  body: JSON.stringify({ scope: "world", storyCount: 5 }),
});
let job = await res.json();
while (job.status === "pending" || job.status === "running") {
  await new Promise((r) => setTimeout(r, 10_000));
  job = await (await fetch(\`\${API}/jobs/\${job.id}\`, { headers })).json();
}
const briefing = await (await fetch(job.resource.url, { headers })).json();
console.log(briefing.stories.map((s) => s.title));
\`\`\`

**Python**

\`\`\`python
import os, time, uuid, requests

API = "${api}"
s = requests.Session()
s.headers["Authorization"] = f"Bearer {os.environ['DS_API_KEY']}"

job = s.post(f"{API}/news/briefings",
             json={"scope": "world", "storyCount": 5},
             headers={"Idempotency-Key": str(uuid.uuid4())}).json()
while job["status"] in ("pending", "running"):
    time.sleep(10)
    job = s.get(f"{API}/jobs/{job['id']}").json()
print([story["title"] for story in s.get(job["resource"]["url"]).json()["stories"]])
\`\`\`

## Authentication & scopes

Send the key as a Bearer token on every request:

\`\`\`
Authorization: Bearer ds_live_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
\`\`\`

Only a SHA-256 of the key is stored; a lost key can't be recovered — revoke it and create another. Keys can expire (30/90/365 days or never) and can be revoked at any time on the Developers page; both answer \`401\`.

Each key carries scopes chosen at creation. A missing scope answers \`403 forbidden\` with \`details.requiredScope\`.

${scopesTable()}

\`GET /me\` works with any scope. \`GET /jobs/{id}\` needs \`news:read\` for briefing jobs and \`research:read\` for research jobs.

## Async jobs

Briefings and research reports take from under a minute to a few minutes, so their \`POST\` answers **202 Accepted** with a **job** and a \`Location\` header pointing at \`GET /jobs/{id}\`.

- \`status\`: \`pending\` → \`running\` (research only) → \`succeeded\` | \`failed\`. It is read live from the briefing or report, so it is never stale.
- \`resource.url\` is the briefing or report to fetch once the job has succeeded.
- Poll every 5–10 seconds, or pass \`webhookUrl\` and get one call when it finishes.

**Briefing dedupe.** There is one briefing per account, date, scope and location (the same rule as the app):

| You send | Answer |
| --- | --- |
| A new date/scope/location | \`202\`, new job, counts toward quota |
| Exactly the same parameters as an existing briefing | \`200\` with that briefing's job, \`"deduplicated": true\`, no quota used |
| Same date/scope/location, different parameters | \`409 conflict\` with \`details.existingBriefingId\` |
| Same slot, but the earlier briefing failed | \`202\`, the briefing is retried |

## Webhooks

Pass an \`https\` \`webhookUrl\` when creating a job. When the job succeeds or fails we \`POST\` once:

\`\`\`json
{
  "id": "<job id>",
  "type": "job.succeeded",
  "createdAt": "2026-10-12T06:34:10.000Z",
  "data": { "job": { "id": "<job id>", "status": "succeeded", "resource": { "...": "..." } } }
}
\`\`\`

Headers: \`X-DS-Event\` (\`job.succeeded\` | \`job.failed\`), \`X-DS-Delivery\` (the job id — use it to ignore duplicates), \`X-DS-Timestamp\` (unix seconds), \`X-DS-Signature\`.

- Answer with any 2xx within 10 seconds. Other answers, timeouts and connection errors are retried 3 times with backoff, then the job's \`webhook.status\` becomes \`failed\`.
- We watch a job for up to 30 minutes; one still running then gets \`webhook.status: "expired"\` and no call — poll it instead.
- URLs must be \`https\` and resolve to public addresses (private, loopback and link-local ranges are refused). Redirects are not followed.

**Verifying the signature.** \`X-DS-Signature\` is \`v1=\` + hex HMAC-SHA256 of \`"<timestamp>.<raw body>"\` keyed with your **webhook signing secret** (Developers page → Webhook signing secret; rotatable). Use the raw request body, compare in constant time and reject timestamps older than 5 minutes.

\`\`\`js
// Node
import crypto from "node:crypto";

export function verifyDsWebhook(rawBody, headers, secret) {
  const ts = headers["x-ds-timestamp"];
  const sig = headers["x-ds-signature"] ?? "";
  if (!ts || Math.abs(Date.now() / 1000 - Number(ts)) > 300) return false;
  const expected = "v1=" + crypto.createHmac("sha256", secret).update(\`\${ts}.\${rawBody}\`).digest("hex");
  return sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
}
\`\`\`

\`\`\`python
# Python
import hmac, hashlib, time

def verify_ds_webhook(raw_body: bytes, headers, secret: str) -> bool:
    ts = headers.get("X-DS-Timestamp", "")
    sig = headers.get("X-DS-Signature", "")
    if not ts.isdigit() or abs(time.time() - int(ts)) > 300:
        return False
    mac = hmac.new(secret.encode(), f"{ts}.".encode() + raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, "v1=" + mac)
\`\`\`

## Errors

Every error has the same shape; \`requestId\` matches the \`X-Request-Id\` response header (send your own \`X-Request-Id\` to correlate logs).

\`\`\`json
{ "error": { "code": "invalid_request", "message": "Request validation failed.",
  "details": { "fields": [{ "in": "body", "path": "storyCount", "message": "Too big: expected number to be <=12" }] },
  "requestId": "req_8f2c1d9e4b7a4c3e" } }
\`\`\`

${errorsTable()}

Switch on \`code\`, not on \`message\`; messages may be reworded.

## Plans & limits

| | Pro |
| --- | --- |
| Requests per key per minute | ${limits.requestsPerMinute} |
| Pipeline jobs per account per UTC day (briefings + research) | ${limits.pipelineJobsPerDay} |
| Active keys per account | ${limits.maxActiveKeys} |
| Request body | 64 KB |

Every authenticated response carries \`X-RateLimit-Limit\`, \`X-RateLimit-Remaining\` and \`X-RateLimit-Reset\` (unix seconds). The per-minute limit is a sliding window; a \`429 rate_limited\` carries \`Retry-After\`. Only accepted pipeline jobs count toward the daily quota — validation errors, deduplicated briefings and idempotent replays don't. \`GET /me\` shows today's usage.

## Pagination

Lists return \`{ "data": [...], "nextCursor": "..." | null }\`. Pass \`nextCursor\` back as \`?cursor=\` (with the same filters) for the next page; \`null\` means the end. Cursors are opaque — don't build or parse them. \`limit\` is 1–50 (default 20). Stories are ordered by \`publishedAt\` then \`id\`, newest first; other lists by creation time.

## Idempotency

\`POST /news/briefings\` and \`POST /research/reports\` accept an \`Idempotency-Key\` header (1–255 printable ASCII characters; a UUID is ideal). For 24 hours:

- the same key with the same request returns the original response again, with \`Idempotent-Replayed: true\` — no second job, no quota;
- the same key with a different request answers \`422 idempotency_key_reused\`;
- the same key while the first request is still being processed answers \`409 conflict\`.

Only successful responses are stored, so a request that failed (4xx/5xx) can be retried with the same key.

## Versioning

The version is in the path (\`/api/v1\`). Within v1 we only make additive changes: new endpoints, new optional parameters, new response fields and new error \`code\`s. Ignore unknown fields. Breaking changes ship as \`/api/v2\`, announced here with at least 3 months of overlap. The machine-readable contract is [\`/api/v1/openapi.json\`](${api}/openapi.json) (OpenAPI 3.1).

## Changelog

${changelog()}
`.trim();
}

/**
 * OpenAPI 3.1 document of the public API, generated from `contract.ts`.
 *
 * Schemas come from zod v4 `z.toJSONSchema`: request bodies and parameters
 * in `io: "input"` mode (defaults make fields optional), responses in
 * `io: "output"`. Schemas with `.meta({ id })` become `components.schemas`
 * entries; every `$defs` reference is rewritten to point there.
 *
 * Build-safe: no database or server imports, so CI can build it.
 */

import { z } from "zod";
import { appBaseUrl } from "@/lib/api/v1/baseUrl";
import {
  COMMON_ERRORS,
  endpoints,
  type EndpointDef,
} from "@/lib/api/v1/contract";
import { API_VERSION, apiDocsMarkdown, ERROR_DESCRIPTIONS } from "@/lib/api/v1/docsContent";
import { API_ERROR_STATUS, type ApiErrorCode } from "@/lib/api/v1/errors";
import { getProApiLimits } from "@/lib/api/v1/limits";
import { errorBodySchema } from "@/lib/api/v1/schemas";

type JsonSchema = Record<string, unknown>;
type Io = "input" | "output";

export const TAGS: { name: string; description: string }[] = [
  { name: "Account", description: "The calling key and its account." },
  { name: "Stories", description: "Public stories from successful briefings and published community stories." },
  { name: "Briefings", description: "Your news briefings. Creating one is an async job." },
  { name: "Research", description: "Stock, ETF and mutual fund research reports. Creating one is an async job." },
  { name: "Jobs", description: "Status of async briefing and research requests." },
  { name: "Instruments", description: "Search Indian listed stocks, ETFs and mutual funds." },
  { name: "Newsletters", description: "Scheduled email digests sent to your account's email." },
];

const ERROR_EXAMPLE_MESSAGES: Record<ApiErrorCode, string> = {
  invalid_request: "Request validation failed.",
  unauthorized: "Invalid API key.",
  plan_required: "The API requires an active Pro plan. Upgrade at /pricing; your keys start working again right away.",
  forbidden: 'This key is missing the "news:write" scope.',
  not_found: "Briefing not found.",
  method_not_allowed: "Method not allowed.",
  conflict: "A briefing for this date, scope and location already exists with different parameters.",
  idempotency_key_reused: "This Idempotency-Key was already used with a different request.",
  payload_too_large: "Request body must be at most 65536 bytes.",
  unsupported_media_type: "Send the body as JSON with Content-Type: application/json.",
  limit_reached: "Maximum 5 newsletters per user",
  rate_limited: "Rate limit of 60 requests per minute exceeded. Retry after 12s.",
  quota_exceeded: "Daily quota of 50 pipeline jobs reached. It resets at 2026-10-13T00:00:00.000Z.",
  internal_error: "Something went wrong on our side. Retry later and quote the requestId if it keeps happening.",
};

const ERROR_EXAMPLE_DETAILS: Partial<Record<ApiErrorCode, unknown>> = {
  invalid_request: {
    fields: [{ in: "body", path: "storyCount", message: "Too big: expected number to be <=12" }],
  },
  forbidden: { requiredScope: "news:write" },
  conflict: { existingBriefingId: "3f6c2a1b-9d8e-4f7a-b6c5-d4e3f2a1b0c9" },
  quota_exceeded: { limit: 50, used: 50, resetsAt: "2026-10-13T00:00:00.000Z" },
};

export function errorExample(code: ApiErrorCode) {
  return {
    error: {
      code,
      message: ERROR_EXAMPLE_MESSAGES[code],
      ...(ERROR_EXAMPLE_DETAILS[code] !== undefined ? { details: ERROR_EXAMPLE_DETAILS[code] } : {}),
      requestId: "req_8f2c1d9e4b7a4c3e7d6b5a49",
    },
  };
}

/** First `.meta({ examples })` entry of a schema, if any. */
export function schemaExample(schema: z.ZodType): unknown {
  const meta = z.globalRegistry.get(schema) as { examples?: unknown[] } | undefined;
  return meta?.examples?.[0];
}

/** Rewrites `#/$defs/X` to `#/components/schemas/X` everywhere in a schema. */
function rewriteRefs(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(rewriteRefs);
  if (node && typeof node === "object") {
    const out: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(node)) {
      out[key] =
        key === "$ref" && typeof value === "string"
          ? value.replace(/^#\/\$defs\//, "#/components/schemas/")
          : rewriteRefs(value);
    }
    return out;
  }
  return node;
}

class SchemaCollector {
  readonly components: Record<string, JsonSchema> = {};

  /** JSON Schema for `schema`; named sub-schemas are hoisted into components. */
  convert(schema: z.ZodType, io: Io): JsonSchema {
    const raw = z.toJSONSchema(schema, {
      io,
      target: "draft-2020-12",
      unrepresentable: "any",
      reused: "inline",
    }) as JsonSchema;
    const { $schema: _ignored, $defs, ...root } = raw;
    void _ignored;
    for (const [id, def] of Object.entries(($defs ?? {}) as Record<string, JsonSchema>)) {
      const converted = rewriteRefs(def) as JsonSchema;
      const existing = this.components[id];
      if (existing && JSON.stringify(existing) !== JSON.stringify(converted)) {
        throw new Error(`OpenAPI: schema id "${id}" has two different shapes (input vs output?)`);
      }
      this.components[id] = converted;
    }
    return rewriteRefs(root) as JsonSchema;
  }
}

function parametersFor(
  schema: z.ZodType | undefined,
  location: "query" | "path",
  collector: SchemaCollector,
): JsonSchema[] {
  if (!schema) return [];
  const json = collector.convert(schema, "input");
  const properties = (json.properties ?? {}) as Record<string, JsonSchema>;
  const required = new Set((json.required ?? []) as string[]);
  return Object.entries(properties).map(([name, propSchema]) => {
    const { description, ...rest } = propSchema;
    return {
      name,
      in: location,
      required: location === "path" || required.has(name),
      ...(typeof description === "string" ? { description } : {}),
      schema: rest,
    };
  });
}

const RATE_LIMIT_HEADERS = {
  "X-Request-Id": { $ref: "#/components/headers/X-Request-Id" },
  "X-RateLimit-Limit": { $ref: "#/components/headers/X-RateLimit-Limit" },
  "X-RateLimit-Remaining": { $ref: "#/components/headers/X-RateLimit-Remaining" },
  "X-RateLimit-Reset": { $ref: "#/components/headers/X-RateLimit-Reset" },
};

function errorResponses(codes: ApiErrorCode[]): Record<string, JsonSchema> {
  const byStatus = new Map<number, ApiErrorCode[]>();
  for (const code of new Set(codes)) {
    const status = API_ERROR_STATUS[code];
    byStatus.set(status, [...(byStatus.get(status) ?? []), code]);
  }
  const out: Record<string, JsonSchema> = {};
  for (const [status, statusCodes] of [...byStatus].sort(([a], [b]) => a - b)) {
    const headers: Record<string, unknown> = { "X-Request-Id": { $ref: "#/components/headers/X-Request-Id" } };
    if (statusCodes.includes("rate_limited") || statusCodes.includes("quota_exceeded")) {
      headers["Retry-After"] = { $ref: "#/components/headers/Retry-After" };
    }
    out[String(status)] = {
      description: statusCodes.map((code) => `\`${code}\`: ${ERROR_DESCRIPTIONS[code]}`).join("\n\n"),
      headers,
      content: {
        "application/json": {
          schema: { $ref: "#/components/schemas/Error" },
          examples: Object.fromEntries(
            statusCodes.map((code) => [code, { summary: code, value: errorExample(code) }]),
          ),
        },
      },
    };
  }
  return out;
}

function successResponse(
  description: string,
  schema: z.ZodType,
  collector: SchemaCollector,
  extraHeaders: Record<string, unknown> = {},
): JsonSchema {
  const example = schemaExample(schema);
  return {
    description,
    headers: { ...RATE_LIMIT_HEADERS, ...extraHeaders },
    content: {
      "application/json": {
        schema: collector.convert(schema, "output"),
        ...(example !== undefined ? { example } : {}),
      },
    },
  };
}

function operationFor(endpoint: EndpointDef, collector: SchemaCollector): JsonSchema {
  const isJob = endpoint.successStatus === 202;
  const parameters = [
    ...parametersFor(endpoint.input.params, "path", collector),
    ...parametersFor(endpoint.input.query, "query", collector),
    ...(endpoint.idempotent ? [{ $ref: "#/components/parameters/IdempotencyKey" }] : []),
    { $ref: "#/components/parameters/RequestId" },
  ];

  const responses: Record<string, JsonSchema> = {
    [String(endpoint.successStatus)]: successResponse(
      endpoint.successDescription,
      endpoint.output,
      collector,
      isJob ? { Location: { $ref: "#/components/headers/Location" } } : {},
    ),
    ...Object.fromEntries(
      (endpoint.extraResponses ?? []).map((r) => [String(r.status), successResponse(r.description, r.schema, collector)]),
    ),
    ...errorResponses([...COMMON_ERRORS, ...endpoint.errors]),
  };

  const notes = [
    endpoint.description,
    endpoint.scope ? `**Scope:** \`${endpoint.scope}\`.` : "**Scope:** any.",
    endpoint.costClass === "pipeline" ? "**Cost:** counts toward the daily pipeline quota when accepted." : null,
    endpoint.idempotent ? "Accepts `Idempotency-Key`." : null,
  ].filter(Boolean);

  let requestBody: JsonSchema | undefined;
  if (endpoint.input.body) {
    const example = schemaExample(endpoint.input.body);
    requestBody = {
      required: true,
      content: {
        "application/json": {
          schema: collector.convert(endpoint.input.body, "input"),
          ...(example !== undefined ? { example } : {}),
        },
      },
    };
  }

  return {
    operationId: endpoint.operationId,
    summary: endpoint.summary,
    description: notes.join("\n\n"),
    tags: endpoint.tags,
    "x-scope": endpoint.scope,
    "x-cost-class": endpoint.costClass,
    parameters,
    ...(requestBody ? { requestBody } : {}),
    responses,
  };
}

export function buildOpenApiDocument(baseUrl: string = appBaseUrl()): JsonSchema {
  const collector = new SchemaCollector();
  collector.convert(errorBodySchema, "output");

  const paths: Record<string, Record<string, JsonSchema>> = {};
  for (const endpoint of Object.values(endpoints) as EndpointDef[]) {
    const item = (paths[endpoint.path] ??= {});
    const method = endpoint.method.toLowerCase();
    if (item[method]) {
      throw new Error(`OpenAPI: duplicate ${endpoint.method} ${endpoint.path}`);
    }
    item[method] = operationFor(endpoint, collector);
  }

  return {
    openapi: "3.1.0",
    jsonSchemaDialect: "https://json-schema.org/draft/2020-12/schema",
    info: {
      title: "Dainik Samachar API",
      version: API_VERSION,
      summary: "News briefings, stock research, instrument search and newsletters. Requires Pro.",
      description: apiDocsMarkdown({ baseUrl, limits: getProApiLimits() }),
    },
    servers: [{ url: `${baseUrl}/api/v1`, description: "Production" }],
    security: [{ bearerAuth: [] }],
    tags: TAGS,
    paths,
    components: {
      securitySchemes: {
        bearerAuth: {
          type: "http",
          scheme: "bearer",
          bearerFormat: "ds_live_<43 base62 chars>",
          description: "API key from Settings → Developers (Pro plan).",
        },
      },
      parameters: {
        IdempotencyKey: {
          name: "Idempotency-Key",
          in: "header",
          required: false,
          description: "Replays the first response for 24h instead of starting a second job.",
          schema: { type: "string", minLength: 1, maxLength: 255 },
          example: "5f2b7c1e-8a9d-4e3f-b2a1-0c9d8e7f6a5b",
        },
        RequestId: {
          name: "X-Request-Id",
          in: "header",
          required: false,
          description: "Your own id (8–128 of `A-Z a-z 0-9 . _ : -`), echoed back and in errors.",
          schema: { type: "string", minLength: 8, maxLength: 128 },
        },
      },
      headers: {
        "X-Request-Id": { description: "Id of this request (also in error bodies).", schema: { type: "string" } },
        "X-RateLimit-Limit": { description: "Requests allowed per minute for this key.", schema: { type: "integer" } },
        "X-RateLimit-Remaining": { description: "Requests left in the current window.", schema: { type: "integer" } },
        "X-RateLimit-Reset": { description: "Unix time (s) when the current window ends.", schema: { type: "integer" } },
        "Retry-After": { description: "Seconds to wait before retrying.", schema: { type: "integer" } },
        Location: { description: "URL of the job (`GET /jobs/{id}`).", schema: { type: "string" } },
      },
      schemas: collector.components,
    },
  };
}

