          const media = response.content?.["application/json"];
          assert.ok(media, `${method} ${path} ${status} has a body`);
          const schema = (media as { schema: object }).schema;
          const validate = ajv.compile({ $schema: "https://json-schema.org/draft/2020-12/schema", ...schema, $id: `${op.operationId}-${status}` });
          const examples = media.example !== undefined ? [media.example] : Object.values(media.examples ?? {}).map((e) => e.value);
          assert.ok(examples.length > 0, `${method} ${path} ${status} has an example`);
          for (const example of examples) {
            assert.ok(validate(example), `${op.operationId} ${status}: ${ajv.errorsText(validate.errors)}`);
          }
