      endpoint.output.parse(example);
      if (endpoint.input.body) {
        endpoint.input.body.parse(schemaExample(endpoint.input.body));
      }
    }
  });
});

export { ajvForContract };

/** Shared with the integration tests: validates a live response against the document. */
function ajvForContract() {
  const doc = buildOpenApiDocument("https://example.com") as {
    paths: Record<string, Record<string, { responses: Record<string, { content?: Record<string, { schema: object }> }> }>>;
    components: { schemas: Record<string, object> };
  };
  const ajv = new Ajv2020({ strict: false, validateFormats: false });
  for (const [id, schema] of Object.entries(doc.components.schemas)) {
    ajv.addSchema(schema, `#/components/schemas/${id}`);
  }
  const cache = new Map<string, ReturnType<typeof ajv.compile>>();
  return (method: string, path: string, status: number, body: unknown): string | null => {
    const key = `${method} ${path} ${status}`;
    let validate = cache.get(key);
    if (!validate) {
      const schema = doc.paths[path]?.[method.toLowerCase()]?.responses[String(status)]?.content?.["application/json"]?.schema;
      if (!schema) return `no schema for ${key}`;
      validate = ajv.compile({ $schema: "https://json-schema.org/draft/2020-12/schema", ...schema, $id: key });
      cache.set(key, validate);
    }
    return validate(body) ? null : `${key}: ${ajv.errorsText(validate.errors)}`;
  };
}

